CREATE TEMP TABLE viewing_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.viewing_check(n text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Viewing check failed: %',n;END IF;INSERT INTO viewing_checks VALUES(n);END;$$;
CREATE FUNCTION pg_temp.viewing_error(n text,s text,c text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE failed boolean:=false;BEGIN BEGIN EXECUTE s;EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>c THEN RAISE;END IF;failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Expected viewing error missing: %',n;END IF;INSERT INTO viewing_checks VALUES(n);END;$$;
CREATE FUNCTION pg_temp.viewing_audit_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action=current_setting('bedos.viewing_fail_action',true) THEN RAISE EXCEPTION 'Synthetic audit failure' USING ERRCODE='23514';END IF;RETURN NEW;END;$$;
CREATE FUNCTION pg_temp.viewing_notify_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('bedos.viewing_notify_fail',true)='yes' AND NEW.related_entity_type='viewing_request' THEN RAISE EXCEPTION 'Synthetic notification failure' USING ERRCODE='23514';END IF;RETURN NEW;END;$$;
CREATE TRIGGER bedos_viewing_test_audit BEFORE INSERT ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION pg_temp.viewing_audit_fail();
CREATE TRIGGER bedos_viewing_test_notification BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION pg_temp.viewing_notify_fail();
DO $test$
DECLARE a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();c uuid:=gen_random_uuid();other uuid:=gen_random_uuid();inactive uuid:=gen_random_uuid();finance uuid:=gen_random_uuid();content uuid:=gen_random_uuid();property uuid;draft uuid;request_id uuid;second_id uuid;sample uuid;event_id uuid;
 result jsonb;v jsonb;events jsonb;before_a bigint;before_e bigint;before_n bigint;code text;r text;p text;f text;old_status text;new_status text;i integer;transition boolean;
BEGIN
 INSERT INTO public.permissions(name) VALUES('viewings.view'),('viewings.manage') ON CONFLICT(name) DO NOTHING;
 INSERT INTO public.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM public.roles r CROSS JOIN public.permissions p WHERE r.name IN('administrator','sales_customer_service') AND p.name IN('viewings.view','viewings.manage') ON CONFLICT DO NOTHING;
 INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT id,id||'@bedos-viewing-test.invalid','{}'::jsonb FROM unnest(ARRAY[a,s,c,other,inactive,finance,content]) id;
 UPDATE public.profiles SET account_status='active',role_id=(SELECT id FROM public.roles WHERE name='customer') WHERE id IN(a,s,c,other,inactive,finance,content);
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='administrator') WHERE id=a;
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='sales_customer_service') WHERE id IN(s,inactive);
 UPDATE public.profiles SET account_status='suspended' WHERE id=inactive;
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='finance') WHERE id=finance;
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='content_manager') WHERE id=content;
 INSERT INTO public.properties(title,slug,property_type,listing_type,status,created_by) VALUES('Viewing SQL fixture','viewing-'||a,'test','test','published',a) RETURNING id INTO property;
 INSERT INTO public.properties(title,slug,property_type,listing_type,status,created_by) VALUES('Draft viewing SQL fixture','viewing-draft-'||a,'test','test','draft',a) RETURNING id INTO draft;
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  FOREACH p IN ARRAY ARRAY['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP PERFORM pg_temp.viewing_check(r||' viewing '||p,NOT has_table_privilege(r,'public.viewing_requests',p));END LOOP;
  FOREACH p IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP PERFORM pg_temp.viewing_check(r||' private events '||p,NOT has_table_privilege(r,'public.viewing_notification_events',p));END LOOP;
  FOREACH f IN ARRAY ARRAY['bedos_read_viewings(uuid,uuid,uuid,text,uuid,uuid,integer,integer,boolean)','bedos_mutate_viewing(uuid,text,uuid,uuid,jsonb,integer)','bedos_viewing_events(uuid,integer,integer)','bedos_deliver_viewing_event(uuid,uuid,boolean)'] LOOP PERFORM pg_temp.viewing_check(r||f,has_function_privilege(r,'public.'||f,'EXECUTE')=(r='service_role'));END LOOP;
 END LOOP;
 PERFORM pg_temp.viewing_error('anonymous mutation denied',format('SELECT public.bedos_mutate_viewing(NULL,''create'',%L)',property),'42501');
 PERFORM pg_temp.viewing_error('suspended mutation denied',format('SELECT public.bedos_mutate_viewing(%L,''create'',%L)',inactive,property),'42501');
 PERFORM pg_temp.viewing_error('finance read denied',format('SELECT public.bedos_read_viewings(%L)',finance),'42501');
 PERFORM pg_temp.viewing_error('content read denied',format('SELECT public.bedos_read_viewings(%L)',content),'42501');
 PERFORM pg_temp.viewing_error('staff cannot submit',format('SELECT public.bedos_mutate_viewing(%L,''create'',%L)',s,property),'42501');
 PERFORM pg_temp.viewing_error('draft property submission denied',format('SELECT public.bedos_mutate_viewing(%L,''create'',%L)',c,draft),'P0409');
 PERFORM pg_temp.viewing_error('publication guard still protects direct reference',format('INSERT INTO public.viewing_requests(property_id,customer_id) VALUES(%L,%L)',draft,c),'P0409');
 FOREACH code IN ARRAY ARRAY['{"message":2}','{"preferred_date":"2026-02-29"}','{"preferred_date":"0000-01-01"}','{"preferred_time":"24:00"}','{"preferred_time":"10:60"}','{"customer_id":"caller"}','[]','null'] LOOP PERFORM pg_temp.viewing_error('strict input '||code,format('SELECT public.bedos_mutate_viewing(%L,''create'',%L,NULL,%L)',c,property,code),'22023');END LOOP;
 result:=public.bedos_mutate_viewing(c,'create',property,NULL,'{"preferred_date":"2000-02-29","preferred_time":"10:30","message":" Hello "}');
 request_id:=(result->'record'->>'id')::uuid;events:=result->'notification_events';
 PERFORM pg_temp.viewing_check('new defaults and normalized preference',result->'record'->>'status'='new' AND result->'record'->>'message'='Hello' AND result->'record'->>'preferred_time'='10:30:00' AND result->'record'->>'version'='1' AND result->'record'->>'customer_id'=c::text);
 PERFORM pg_temp.viewing_check('customer and two eligible staff events',jsonb_array_length(events)>=3 AND (SELECT count(*) FROM public.viewing_notification_events WHERE viewing_id=request_id AND recipient_id IN(a,s,c))=3 AND NOT EXISTS(SELECT 1 FROM public.viewing_notification_events WHERE viewing_id=request_id AND recipient_id IN(inactive,finance,content)));
 v:=public.bedos_read_viewings(c);PERFORM pg_temp.viewing_check('customer bounded own list',v->'pagination'->>'total'='1' AND jsonb_array_length(v->'data')=1);
 v:=public.bedos_read_viewings(other);PERFORM pg_temp.viewing_check('other customer sees no foreign record',v->'pagination'->>'total'='0');
 v:=public.bedos_read_viewings(a,NULL,NULL,'new',c,NULL,2,25);PERFORM pg_temp.viewing_check('empty filtered page retains count',v->'pagination'->>'total'='1' AND v->'data'='[]');
 PERFORM pg_temp.viewing_error('customer cannot staff filter',format('SELECT public.bedos_read_viewings(%L,NULL,NULL,NULL,%L)',c,other),'42501');
 PERFORM pg_temp.viewing_error('foreign item hidden',format('SELECT public.bedos_read_viewings(%L,%L,%L)',other,property,request_id),'P0002');
 PERFORM pg_temp.viewing_error('cross parent hidden',format('SELECT public.bedos_read_viewings(%L,%L,%L)',a,draft,request_id),'P0002');
 PERFORM pg_temp.viewing_error('oversized list rejected',format('SELECT public.bedos_read_viewings(%L,NULL,NULL,NULL,NULL,NULL,1,101)',a),'22023');
 SELECT jsonb_agg(id ORDER BY id) INTO events FROM public.viewing_notification_events WHERE viewing_id=request_id AND recipient_id IN(a,s,c);
 FOR i IN 0..2 LOOP
  event_id:=(events->>i)::uuid;v:=public.bedos_deliver_viewing_event(c,event_id);PERFORM pg_temp.viewing_check('new notification materialized '||i,v->>'state'='recorded');
  v:=public.bedos_deliver_viewing_event(a,event_id,true);PERFORM pg_temp.viewing_check('event replay stays recorded '||i,v->>'state'='recorded');
 END LOOP;
 PERFORM pg_temp.viewing_check('three deduplicated viewing records', (SELECT count(*) FROM public.notifications WHERE related_entity_type='viewing_request' AND related_entity_id=request_id)=3);
 PERFORM pg_temp.viewing_error('sales event queue denied',format('SELECT public.bedos_viewing_events(%L)',s),'42501');
 PERFORM pg_temp.viewing_error('customer event queue denied',format('SELECT public.bedos_viewing_events(%L)',c),'42501');
 PERFORM pg_temp.viewing_error('sales manual event retry denied',format('SELECT public.bedos_deliver_viewing_event(%L,%L,true)',s,event_id),'42501');
 v:=public.bedos_viewing_events(a);PERFORM pg_temp.viewing_check('administrator safe queue fields',(v->'pagination'->>'total')::integer>=3 AND NOT(v->'events'->0 ? 'lease_token') AND NOT(v->'events'->0 ? 'recipient_id'));
 PERFORM pg_temp.viewing_error('customer cannot assign',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,%L,1)',c,property,request_id,jsonb_build_object('assigned_to',s)),'42501');
 PERFORM pg_temp.viewing_error('customer cancellation cannot edit message',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"status":"cancelled","message":"a"}'',1)',c,property,request_id),'42501');
 result:=public.bedos_mutate_viewing(c,'update',property,request_id,'{"message":"Edited"}',1);PERFORM pg_temp.viewing_check('owner edits only while new',result->'record'->>'version'='2' AND result->'record'->>'message'='Edited');
 PERFORM pg_temp.viewing_error('stale edit rejected',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"message":"Stale"}'',1)',c,property,request_id),'P0001');
 PERFORM pg_temp.viewing_error('invalid finance assignee',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,%L,2)',a,property,request_id,jsonb_build_object('assigned_to',finance)),'22023');
 PERFORM pg_temp.viewing_error('inactive assignee',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,%L,2)',a,property,request_id,jsonb_build_object('assigned_to',inactive)),'22023');
 result:=public.bedos_mutate_viewing(s,'update',property,request_id,jsonb_build_object('status','contacted','assigned_to',s),2);
 PERFORM pg_temp.viewing_check('staff contacts and assigns atomically',result->'record'->>'status'='contacted' AND result->'record'->>'version'='3' AND result->'record'->>'assigned_to'=s::text);
 PERFORM pg_temp.viewing_error('customer cannot edit after processing',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"message":"Late"}'',3)',c,property,request_id),'42501');
 UPDATE public.properties SET status='unavailable' WHERE id=property;
 v:=public.bedos_read_viewings(c,property,request_id);PERFORM pg_temp.viewing_check('withdrawal preserves existing customer read',v->>'id'=request_id::text);
 result:=public.bedos_mutate_viewing(s,'update',property,request_id,'{"status":"scheduled"}',3);PERFORM pg_temp.viewing_check('existing request scheduling preserved after withdrawal',result->'record'->>'status'='scheduled' AND result->'record'->>'version'='4');
 PERFORM pg_temp.viewing_error('scheduled request cannot clear time',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"preferred_time":null}'',4)',s,property,request_id),'22023');
 UPDATE public.profiles SET account_status='suspended' WHERE id=s;
 result:=public.bedos_mutate_viewing(a,'update',property,request_id,'{"status":"completed"}',4);PERFORM pg_temp.viewing_check('can complete after original assignee suspension',result->'record'->>'version'='5');
 UPDATE public.profiles SET account_status='active' WHERE id=s;
 PERFORM pg_temp.viewing_error('completed request immutable',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"message":"Late"}'',5)',a,property,request_id),'P0001');
 PERFORM pg_temp.viewing_error('stale administrator deletion',format('SELECT public.bedos_mutate_viewing(%L,''delete'',%L,%L,''{}'',4)',a,property,request_id),'P0001');
 PERFORM pg_temp.viewing_error('sales cannot delete',format('SELECT public.bedos_mutate_viewing(%L,''delete'',%L,%L,''{}'',5)',s,property,request_id),'42501');
 result:=public.bedos_mutate_viewing(a,'delete',property,request_id,'{}',5);PERFORM pg_temp.viewing_check('administrator versioned deletion',NOT EXISTS(SELECT 1 FROM public.viewing_requests WHERE id=request_id));
 FOR event_id IN SELECT id FROM public.viewing_notification_events WHERE viewing_id=request_id AND state='pending' LOOP v:=public.bedos_deliver_viewing_event(a,event_id,true);IF v->>'state'<>'suppressed' THEN RAISE EXCEPTION 'Deleted request event not suppressed';END IF;END LOOP;
 PERFORM pg_temp.viewing_check('deleted request pending events suppressed',NOT EXISTS(SELECT 1 FROM public.viewing_notification_events WHERE viewing_id=request_id AND state='pending'));
 UPDATE public.properties SET status='published' WHERE id=property;
 FOREACH old_status IN ARRAY ARRAY['new','contacted','scheduled','completed','cancelled'] LOOP
  FOREACH new_status IN ARRAY ARRAY['new','contacted','scheduled','completed','cancelled'] LOOP
   INSERT INTO public.viewing_requests(property_id,customer_id,assigned_to,preferred_date,preferred_time,status) VALUES(property,c,s,'2027-01-01','10:00',old_status) RETURNING id INTO sample;
   transition:=CASE old_status WHEN 'new' THEN new_status IN('contacted','cancelled') WHEN 'contacted' THEN new_status IN('scheduled','cancelled') WHEN 'scheduled' THEN new_status IN('completed','cancelled') ELSE false END;
   IF transition THEN result:=public.bedos_mutate_viewing(a,'update',property,sample,jsonb_build_object('status',new_status),1);PERFORM pg_temp.viewing_check(old_status||' to '||new_status,result->'record'->>'status'=new_status AND result->'record'->>'version'='2');
   ELSE PERFORM pg_temp.viewing_error(old_status||' to '||new_status,format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,%L,1)',a,property,sample,jsonb_build_object('status',new_status)),'P0001');END IF;
  END LOOP;
 END LOOP;
 result:=public.bedos_mutate_viewing(other,'create',property);second_id:=(result->'record'->>'id')::uuid;events:=result->'notification_events';SELECT id INTO event_id FROM public.viewing_notification_events WHERE viewing_id=second_id AND event_type='customer_new';
 PERFORM set_config('bedos.viewing_notify_fail','yes',true);
 v:=public.bedos_deliver_viewing_event(other,event_id);PERFORM pg_temp.viewing_check('notification insertion failure remains pending',v->>'state'='pending' AND (SELECT state='pending' AND attempts=1 AND last_error_code='23514' FROM public.viewing_notification_events WHERE id=event_id));
 PERFORM pg_temp.viewing_check('notification failure preserves committed request',EXISTS(SELECT 1 FROM public.viewing_requests WHERE id=second_id AND version=1 AND status='new') AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE related_entity_id=second_id));
 PERFORM pg_temp.viewing_error('failed event cooldown enforced',format('SELECT public.bedos_deliver_viewing_event(%L,%L,true)',a,event_id),'P0001');
 PERFORM set_config('bedos.viewing_notify_fail','no',true);UPDATE public.viewing_notification_events SET lease_until=now()-interval '1 minute' WHERE id=event_id;
 v:=public.bedos_deliver_viewing_event(a,event_id,true);PERFORM pg_temp.viewing_check('administrator retry records one notification',v->>'state'='recorded' AND (SELECT count(*) FROM public.notifications WHERE related_entity_id=second_id)=1);
 SELECT count(*) INTO before_a FROM public.audit_logs WHERE entity_id=second_id;SELECT count(*) INTO before_e FROM public.viewing_notification_events WHERE viewing_id=second_id;
 PERFORM set_config('bedos.viewing_fail_action','viewing_request_updated',true);
 PERFORM pg_temp.viewing_error('business audit failure rolls back entire mutation',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"status":"contacted"}'',1)',a,property,second_id),'23514');
 PERFORM set_config('bedos.viewing_fail_action','',true);
 PERFORM pg_temp.viewing_check('audit failure left version and event count intact',(SELECT status='new' AND version=1 FROM public.viewing_requests WHERE id=second_id) AND (SELECT count(*) FROM public.audit_logs WHERE entity_id=second_id)=before_a AND (SELECT count(*) FROM public.viewing_notification_events WHERE viewing_id=second_id)=before_e);
 result:=public.bedos_mutate_viewing(other,'update',property,second_id,'{"status":"cancelled"}',1);PERFORM pg_temp.viewing_check('owner cancels own new request',result->'record'->>'status'='cancelled' AND result->'record'->>'version'='2');
 SELECT id INTO event_id FROM public.viewing_notification_events WHERE viewing_id=second_id AND event_type='staff_new' AND recipient_id=s;
 v:=public.bedos_deliver_viewing_event(a,event_id,true);PERFORM pg_temp.viewing_check('cancelled new-request staff notice suppressed',v->>'state'='suppressed');
 -- Explicit target eligibility and permission removal are evaluated again at commit/materialization.
 SELECT id INTO event_id FROM public.viewing_notification_events WHERE viewing_id=second_id AND event_type='customer_status';
 UPDATE public.profiles SET account_status='suspended' WHERE id=other;
 v:=public.bedos_deliver_viewing_event(a,event_id,true);PERFORM pg_temp.viewing_check('inactive customer target suppressed',v->>'state'='suppressed');
 UPDATE public.profiles SET account_status='active' WHERE id=other;
 -- BEGIN LOCAL PERMISSION REVOCATION PROBE
 DELETE FROM public.role_permissions WHERE role_id=(SELECT id FROM public.roles WHERE name='sales_customer_service') AND permission_id=(SELECT id FROM public.permissions WHERE name='viewings.manage');
 PERFORM pg_temp.viewing_error('revoked management permission takes effect',format('SELECT public.bedos_mutate_viewing(%L,''update'',%L,%L,''{"message":"Denied"}'',2)',s,property,second_id),'42501');
 -- END LOCAL PERMISSION REVOCATION PROBE
 result:=public.bedos_mutate_viewing(c,'create',property);sample:=(result->'record'->>'id')::uuid;SELECT id INTO event_id FROM public.viewing_notification_events WHERE viewing_id=sample AND event_type='customer_new';
 result:=public.bedos_mutate_viewing(c,'update',property,sample,'{"status":"cancelled"}',1);v:=public.bedos_deliver_viewing_event(a,event_id,true);
 PERFORM pg_temp.viewing_check('late customer new-request confirmation suppressed after cancellation',v->>'state'='suppressed' AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE related_entity_id=sample));
 PERFORM pg_temp.viewing_check('order notification uniqueness retained',EXISTS(SELECT 1 FROM pg_indexes WHERE schemaname='public' AND indexname='notifications_one_order_confirmed_per_order'));
END;$test$;
SELECT jsonb_build_object('assertions',count(*),'passed',true) FROM viewing_checks;
